        if name.startswith('dot_'):
            name = '.' + name[4:]
            changed = True
        for prefix in prefixes:
            if name.startswith(prefix):
                name = name[len(prefix):]
                changed = True
                break
    return name


def managed_paths(source):
    result = set()
    if not source or not os.path.isdir(source):
        return result
    for root, dirs, files in os.walk(source):
        dirs[:] = [d for d in dirs if d not in ('.git',)]
        for name in files + dirs:
            if name.startswith('.') and name in ('.chezmoidata.json', '.chezmoiignore', '.chezmoiversion'):
                continue
            rel = os.path.relpath(os.path.join(root, name), source)
            parts = rel.split(os.sep)
            decoded = []
            for part in parts:
                if part.endswith('.tmpl'):
                    part = part[:-5]
                decoded.append(decode_source_name(part))
            result.add(os.path.normpath(os.path.join(*decoded)))
    patterns = ignored_paths(source)
    return {path for path in result if not is_ignored(path, patterns)}


def source_relative_path(target_rel, source):
    """Return the encoded source path corresponding to a target-relative path."""
    if not os.path.isdir(source):
        return None
    target_rel = os.path.normpath(target_rel)
    for root, dirs, files in os.walk(source):
        for name in files + dirs:
            rel = os.path.relpath(os.path.join(root, name), source)
            parts = rel.split(os.sep)
            decoded = []
            for part in parts:
                if part.endswith('.tmpl'):
                    part = part[:-5]
                decoded.append(decode_source_name(part))
            if os.path.normpath(os.path.join(*decoded)) == target_rel:
                return rel
    return None


def ignored_paths(source):
    ignored = set()
    if not source:
        return ignored
    f = os.path.join(source, '.chezmoiignore')
    try:
        patterns = [x.strip() for x in open(f, encoding='utf-8') if x.strip() and not x.lstrip().startswith('#')]
    except OSError:
        return ignored
    return patterns


def is_ignored(path, patterns):
    path = path.replace(os.sep, '/')
    for pattern in patterns:
        while pattern.startswith('./'):
            pattern = pattern[2:]
        pattern = pattern.rstrip('/')
        if fnmatch.fnmatchcase(path, pattern) or fnmatch.fnmatchcase('/' + path, '/' + pattern):
            return True
        if pattern and path.startswith(pattern + '/'):
            return True
    return False


