def _source_name(target: str) -> str:
    parts = target.replace("\\", "/").split("/")
    out = []
    for part in parts:
        if not part:
            continue
        if part.startswith("."):
            part = "dot_" + part[1:]
        out.append(part)
    return "/".join(out)


